#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal static class ColumnFillTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();MainWindow main=null;try{Action<bool,string> check=delegate(bool ok,string text){if(!ok)throw new Exception(text);log.Add(text);};main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false};main.Show();NavigationTests.WaitPanels(main);foreach(double width in new[]{900.0,1200.0,1600.0}){main.Width=width;NavigationTests.Wait(System.Threading.Tasks.Task.Delay(80));main.UpdateLayout();foreach(var panel in FluentUiTests.Children<FilePanel>(main))panel.VerifyFilledColumns(check);}main.UpdateLayout();NextStageTests.Draw(main,Path.Combine(root,"columns.png"));var hamburger=FluentUiTests.Children<StackPanel>(main).Single(x=>Convert.ToString(x.Tag)=="menu-hamburger");var lines=hamburger.Children.OfType<System.Windows.Shapes.Rectangle>().ToArray();check(lines.Length==3&&lines.All(x=>x.Width==18&&x.Height==2),"menu icon contains three equal geometric strokes");main.Close();main=null;File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count}));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),String.Join("\n",log)+"\n"+ex);return 1;}finally{if(main!=null)main.Close();}}
 }
 public partial class FilePanel {
  internal void VerifyFilledColumns(Action<bool,string> check){RestorePanelView(new PanelView());UpdateLayout();ObserveColumnViewport();foreach(double width in new[]{40.0,90.0,170.0,320.0}){BaseColumn(3).Width=width;FitColumns("Modified");UpdateLayout();check(Math.Abs(view.Columns.Sum(x=>x.Width)-ColumnRoom)<.1,"visible columns exactly fill viewport after date resize to "+width);check(BaseColumn(3).Width>=130,"date cannot shrink below readable minimum");var date=BaseColumn(3);double edge=view.Columns.Take(view.Columns.IndexOf(date)+1).Sum(x=>x.Width);check(Math.Abs(edge-ColumnRoom)<.1,"date stays pinned to the right edge");}SetBaseColumnVisible(2,false);FitColumns();check(Math.Abs(view.Columns.Sum(x=>x.Width)-ColumnRoom)<.1,"hiding size redistributes space without a blank tail");SetBaseColumnVisible(2,true);FitColumns();}
 }
}
#endif
